questions.explanation:
## Why This Is Asked
Tests bridging a C object with Go, memory ownership, and safe cross-language concurrency using CGO. It also touches resource lifecycle (Close) and error handling when C returns NULL.

## Key Concepts
- CGO bindings for C structs and lifecycle
- Memory ownership and Free/Close semantics
- Thread-safety in C with a mutex vs. Go-level synchronization
- Cross-language error handling and result propagation

## Code Example
```c
// counter.h
typedef struct AtomicCounter AtomicCounter;
AtomicCounter* ac_new(void);
void ac_inc(AtomicCounter* ac);
int ac_get(AtomicCounter* ac);
void ac_free(AtomicCounter* ac);
```
```c
// counter.c (stub with mutex)
#include <stdlib.h>
#include <pthread.h>
typedef struct AtomicCounter {
  int val;
  pthread_mutex_t m;
} AtomicCounter;
AtomicCounter* ac_new(void){ AtomicCounter* a = malloc(sizeof(AtomicCounter)); a->val=0; pthread_mutex_init(&a->m, NULL); return a; }
void ac_inc(AtomicCounter* a){ pthread_mutex_lock(&a->m); a->val++; pthread_mutex_unlock(&a->m); }
int ac_get(AtomicCounter* a){ pthread_mutex_lock(&a->m); int v=a->val; pthread_mutex_unlock(&a->m); return v; }
void ac_free(AtomicCounter* a){ pthread_mutex_destroy(&a->m); free(a); }
```
```go
// counter.go
package counter
/*
#include "counter.h"
#include <stdlib.h>
*/
import "C"
import (
  "errors"
)

type AtomicCounter struct{ c *C.AtomicCounter }

func NewAtomicCounter() (*AtomicCounter, error) {
  p := C.ac_new()
  if p == nil {
    return nil, errors.New("failed to create AtomicCounter")
  }
  return &AtomicCounter{c: p}, nil
}

func (a *AtomicCounter) Inc() { C.ac_inc(a.c) }
func (a *AtomicCounter) Get() int { return int(C.ac_get(a.c)) }
func (a *AtomicCounter) Close() { C.ac_free(a.c) }
```

```go
// main.go
package main
import (
  "fmt"
  "sync"
  "counter" // path to the package
)

func main() {
  ac, _ := counter.NewAtomicCounter()
  var wg sync.WaitGroup
  increments := 1000
  for i := 0; i < 3; i++ {
    wg.Add(1)
    go func() {
      for j := 0; j < increments; j++ { ac.Inc() }
      wg.Done()
    }()
  }
  wg.Wait()
  fmt.Println("final:", ac.Get())
  ac.Close()
}
```

## Follow-up Questions
- How would you support multiple independent counters in the same process?
- What changes to CGO flags or build tags would you add to ensure pthreads compatibility on all platforms?

## Why This Is Asked
Tests knowledge of CGO cross-language callbacks, memory ownership, and safe cancellation in a realistic long-running task.

## Key Concepts
- CGO callbacks from C to Go
- go:export integration
- Per-call context via cgo.Handle
- Thread lifecycle and cancellation
- Resource cleanup across language boundaries

## Code Example

```c
// header: proc.h
#ifndef PROC_H
#define PROC_H
#include <stdint.h>
#include <stdlib.h>

typedef void (*progress_cb)(int pct, void* user);
void process_data_async(const uint8_t* data, size_t len, progress_cb cb, void* user);
void abort_processing(void* handle);
#endif
```

```c
// implementation: proc.c
#include "proc.h"
#include <pthread.h>
#include <unistd.h>

typedef struct {
    const uint8_t* data;
    size_t len;
    progress_cb cb;
    void* user;
    int cancelled;
    pthread_t thread;
} process_context_t;

static void* process_thread(void* arg) {
    process_context_t* ctx = (process_context_t*)arg;
    for (int i = 0; i <= 100 && !ctx->cancelled; i++) {
        usleep(10000); // simulate work
        if (ctx->cb) ctx->cb(i, ctx->user);
    }
    return NULL;
}

void process_data_async(const uint8_t* data, size_t len, progress_cb cb, void* user) {
    process_context_t* ctx = malloc(sizeof(process_context_t));
    ctx->data = data;
    ctx->len = len;
    ctx->cb = cb;
    ctx->user = user;
    ctx->cancelled = 0;
    pthread_create(&ctx->thread, NULL, process_thread, ctx);
    pthread_detach(ctx->thread);
}

void abort_processing(void* handle) {
    process_context_t* ctx = (process_context_t*)handle;
    if (ctx) ctx->cancelled = 1;
}
```

```go
// binding: proc.go
package main

/*
#cgo CFLAGS: -I.
#cgo LDFLAGS: -L. -lproc
#include "proc.h"
#include <stdint.h>

//export progressCallback
void progressCallback(int pct, void* user) {
    // This will be implemented in Go
}
*/
import "C"
import (
    "runtime"
    "sync"
    "unsafe"
)

type processor struct {
    ch    chan int
    ctx   *C.process_context_t
    mutex sync.Mutex
}

var processors = make(map[uintptr]*processor)
var processorsMutex sync.Mutex

//export progressCallback
func progressCallback(pct C.int, user unsafe.Pointer) {
    handle := uintptr(user)
    processorsMutex.Lock()
    defer processorsMutex.Unlock()

    if proc, exists := processors[handle]; exists {
        select {
        case proc.ch <- int(pct):
        default:
        }
    }
}

func ProcessData(data []byte) (<-chan int, func()) {
    ch := make(chan int, 10)
    proc := &processor{ch: ch}

    handle := C.malloc(C.size_t(unsafe.Sizeof(uintptr(0))))
    *(*uintptr)(handle) = uintptr(unsafe.Pointer(proc))

    processorsMutex.Lock()
    processors[uintptr(handle)] = proc
    processorsMutex.Unlock()

    cdata := (*C.uint8_t)(unsafe.Pointer(&data[0]))
    C.process_data_async(cdata, C.size_t(len(data)), 
        (C.progress_cb)(C.progressCallback), handle)

    cancel := func() {
        proc.mutex.Lock()
        defer proc.mutex.Unlock()

        if proc.ctx != nil {
            C.abort_processing(unsafe.Pointer(proc.ctx))
        }

        processorsMutex.Lock()
        delete(processors, uintptr(handle))
        processorsMutex.Unlock()

        C.free(handle)
        close(ch)
    }

    runtime.SetFinalizer(proc, func(*processor) {
        cancel()
    })

    return ch, cancel
}
```

```go
// main.go
package main

import (
    "fmt"
    "time"
)

func main() {
    data1 := make([]byte, 1000)
    data2 := make([]byte, 2000)

    ch1, cancel1 := ProcessData(data1)
    ch2, cancel2 := ProcessData(data2)

    go func() {
        for pct := range ch1 {
            fmt.Printf("Processor 1: %d%%\n", pct)
        }
    }()

    go func() {
        for pct := range ch2 {
            fmt.Printf("Processor 2: %d%%\n", pct)
        }
    }()

    time.Sleep(2 * time.Second)
